public class Solution {
    public static void selectionSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] < arr[minIdx]) minIdx = j;
            }
            int temp = arr[minIdx];
            arr[minIdx] = arr[i];
            arr[i] = temp;
        }
    }
}

public class Solution {
    public static int countMatches(int[] arr) {
        int i = 0, matches = 0, n = arr.length;
        while (i < n) {
            int j = i + 1;
            while (j < n) {
                if (arr[i] == arr[j]) matches++;
                j++;
            }
            i++;
        }
        return matches;
    }
}

public class Solution {
    private static boolean containsNegation(int[] nums, int target) {
        for (int x : nums) if (x == -target) return true;
        return false;
    }
    public static int countSymmetric(int[] nums) {
        int count = 0;
        for (int x : nums) {
            if (containsNegation(nums, x)) count++;
        }
        return count;
    }
}

public class Solution {
    public static int sumMatrix(int[][] grid) {
        int n = grid.length, sum = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                sum += grid[r][c];
            }
        }
        return sum;
    }
}

public class Solution {
    public static int threeSumBruteForce(int[] nums) {
        int n = nums.length, count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    if (nums[i] + nums[j] + nums[k] == 0) count++;
                }
            }
        }
        return count;
    }
}

public class Solution {
    public static int[][] multiplyMatrices(int[][] a, int[][] b) {
        int n = a.length;
        int[][] c = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    c[i][j] += a[i][k] * b[k][j];
                }
            }
        }
        return c;
    }
}

public class Solution {
    public static int sweep3D(int n) {
        int i = 0, total = 0;
        while (i < n) {
            int j = 0;
            while (j < n) {
                int k = 0;
                while (k < n) {
                    total += (i + j + k);
                    k++;
                }
                j++;
            }
            i++;
        }
        return total;
    }
}

public class Solution {
    private static boolean linearExists(int[] arr, int val) {
        for (int x : arr) if (x == val) return true;
