public class Solution {
    private static void backtrack(int[] nums, int idx, java.util.List<Integer> curr, java.util.List<java.util.List<Integer>> res) {
        if (idx == nums.length) {
            res.add(new java.util.ArrayList<>(curr));
            return;
        }
        backtrack(nums, idx + 1, curr, res);
        curr.add(nums[idx]);
        backtrack(nums, idx + 1, curr, res);
        curr.remove(curr.size() - 1);
    }
    public static java.util.List<java.util.List<Integer>> subsets(int[] nums) {
        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
        backtrack(nums, 0, new java.util.ArrayList<>(), res);
        return res;
    }
}

public class Solution {
    public static int knapSack(int W, int[] wt, int[] val, int n) {
        if (n == 0 || W == 0) return 0;
        if (wt[n - 1] > W) return knapSack(W, wt, val, n - 1);
        return Math.max(
            val[n - 1] + knapSack(W - wt[n - 1], wt, val, n - 1),
            knapSack(W, wt, val, n - 1)
        );
    }
}

public class Solution {
    public static int countPaths(int n, int target) {
        if (target == 0) return 1;
        if (n <= 0 || target < 0) return 0;
        return countPaths(n - 1, target - n) + countPaths(n - 1, target);
    }
}
